"""Actual pinned PostgreSQL services generated by both product profiles."""

import json
import io
import os
from pathlib import Path
import secrets
import subprocess
import tempfile
import tarfile
import time
from urllib.request import Request, urlopen

from vpn_orbit.app_lifecycle import Lifecycle, ROOT
from vpn_orbit.app_archive import capture as capture_app, restore as restore_app, transfer
from vpn_orbit.app_postgres import promote, query, restore, settings, write_encrypted
from vpn_orbit.app_profiles import canonical, digest
from vpn_orbit.errors import Denied


def ready(app, service, cid):
    deadline = time.monotonic() + 100
    while not app.healthy({"containers": {service: {"Id": cid}}}):
        if time.monotonic() >= deadline:
            raise RuntimeError("Product database or cache did not become healthy")
        time.sleep(1)


def main():
    if (os.geteuid() != 0 or os.environ.get("GITHUB_ACTIONS") != "true"
            or os.environ.get("RUNNER_ENVIRONMENT") != "github-hosted" or ROOT.exists()):
        raise SystemExit("Disposable GitHub-hosted VM required")
    pins = json.loads((Path(__file__).resolve().parents[2] / "deploy/application-images.json").read_text())["images"]
    profiles = ["remnawave-panel", "bedolaga-bot"]
    identity = "01JCYQZ4T9V8MNVYEH3D2M7Q1A"
    spec = {"v": 1, "id": identity, "profiles": profiles,
            "images": {name: pins[name] for name in (*profiles, "postgres", "redis")},
            "settings": {
                "remnawave-panel": {"database_password": secrets.token_hex(32), "app_secret": secrets.token_hex(32),
                                    "metrics_password": secrets.token_hex(32), "domain": "panel.fixture.invalid",
                                    "subscription_domain": "sub.fixture.invalid"},
                "bedolaga-bot": {"panel_url": "https://panel.fixture.invalid", "panel_api_key": secrets.token_hex(32),
                                 "bot_token": "123456:" + "x" * 40, "admin_ids": "123",
                                 "database_password": secrets.token_hex(32), "api_token": secrets.token_hex(32),
                                 "jwt_secret": secrets.token_hex(32)},
            }}
    Lifecycle.configure(spec)
    app = Lifecycle(identity)
    _, document, _ = app.configuration()
    for image in spec["images"].values():
        app.acquire_image(image)
    app.compose(document, "create", "--no-build", "--pull", "never")
    inventory = app.inventory(document)
    with app.journal.write() as db:
        db.execute("UPDATE installation SET inventory=? WHERE id=1", (canonical(inventory).decode(),))
    os.umask(0o077)
    with tempfile.TemporaryDirectory(dir="/run") as temp:
        root = Path(temp)
        key = root / "fixture.identity"
        keygen = os.environ["VPN_ORBIT_PG_AGE_KEYGEN"]
        subprocess.run([keygen, "-o", key], check=True, capture_output=True)
        recipient = subprocess.check_output([keygen, "-y", key], text=True).strip()
        for service in ("panel-db", "bot-db"):
            cid = inventory["containers"][service]["Id"]
            app.docker("container", "start", cid)
            ready(app, service, cid)
            query(cid, "orbit", "CREATE TABLE fixture (value text); INSERT INTO fixture VALUES ('captured');")
            archive = root / (service + ".age")
            binding = digest(spec)
            with app.locked():
                selected, scope, _ = settings(app, service, binding)
                checksum = write_encrypted(archive, scope, selected, recipient)
            query(cid, "orbit", "UPDATE fixture SET value='live';")
            try:
                restore(app, service, binding, archive, key, "0" * 64)
            except Denied as error:
                assert error.code == "APP_POSTGRES_DIGEST_MISMATCH"
            else:
                raise AssertionError("Wrong digest accepted")
            result = restore(app, service, binding, archive, key, checksum)
            assert query(cid, result["database"], "SELECT value FROM fixture") == "captured"
            assert query(cid, "orbit", "SELECT value FROM fixture") == "live"
            redis = inventory["containers"][service.replace("-db", "-redis")]["Id"]
            app.docker("container", "start", redis)
            try:
                promote(app, service, binding, checksum)
            except Denied as error:
                assert error.code == "APP_POSTGRES_STOP_APPLICATION_FIRST"
            else:
                raise AssertionError("Active product workload was allowed during promotion")
            app.docker("container", "stop", redis)
            promoted = promote(app, service, binding, checksum)
            assert promoted == promote(app, service, binding, checksum)
            assert query(cid, "orbit", "SELECT value FROM fixture") == "captured"
            assert query(cid, promoted["previous_database"], "SELECT value FROM fixture") == "live"
            print(f"Verified encrypted snapshot, transactional restore and safe promotion for {service}.", flush=True)
        for service in ("panel-db", "bot-db"):
            app.docker("container", "stop", "--time", "30", inventory["containers"][service]["Id"])
        redis = inventory["containers"]["bot-redis"]["Id"]
        app.docker("container", "start", redis)
        ready(app, "bot-redis", redis)
        assert app.docker("exec", redis, "redis-cli", "SET", "fixture", "preserved").strip() == "OK"
        assert app.docker("exec", redis, "redis-cli", "SAVE").strip() == "OK"
        app.docker("container", "stop", redis)
        with tempfile.TemporaryFile() as payload:
            with tarfile.open(fileobj=payload, mode="w", format=tarfile.USTAR_FORMAT) as archive:
                data = b"synthetic Bedolaga upload"
                entry = tarfile.TarInfo("fixture.dat")
                entry.size = len(data)
                entry.mode = 0o600
                archive.addfile(entry, io.BytesIO(data))
            payload.seek(0)
            transfer(app, spec, document["volumes"]["bot-uploads"], writing=True, data=payload)
        full = root / "full.age"
        capture = capture_app(app.identity, digest(spec), recipient, full)
        duplicate = app.identity[:-1] + "B"
        copied = restore_app(full, key, capture["sha256"], duplicate)
        assert copied["status"] == "RESTORED_STOPPED"
        target = Lifecycle(duplicate)
        restored_spec, document, result = target.configuration()
        assert {**restored_spec, "id": identity} == spec
        owned = target.verify_inventory(document, result)
        for service in ("panel-db", "bot-db"):
            cid = owned["containers"][service]["Id"]
            target.docker("container", "start", cid)
            ready(target, service, cid)
            assert query(cid, "orbit", "SELECT value FROM fixture") == "captured"
        redis = owned["containers"]["bot-redis"]["Id"]
        target.docker("container", "start", redis)
        ready(target, "bot-redis", redis)
        assert target.docker("exec", redis, "redis-cli", "GET", "fixture").strip() == "preserved"
        with tempfile.TemporaryFile() as payload:
            transfer(target, restored_spec, document["volumes"]["bot-uploads"], data=payload)
            payload.seek(0)
            with tarfile.open(fileobj=payload, mode="r:") as archive:
                assert archive.extractfile("./fixture.dat").read() == b"synthetic Bedolaga upload"
        for service in ("panel-redis", "remnawave-panel"):
            cid = owned["containers"][service]["Id"]
            target.docker("container", "start", cid)
            ready(target, service, cid)
        request = Request("http://127.0.0.1:3000/api/auth/status", headers={
            "Host": "panel.fixture.invalid", "X-Forwarded-Proto": "https", "X-Forwarded-For": "127.0.0.1"})
        with urlopen(request, timeout=8) as response:
            assert response.status == 200 and isinstance(json.load(response), dict)
        assert app.verify_inventory(*app.configuration()[1:]) == inventory
        print("Verified restored volumes, both PostgreSQL services, Bedolaga data, and actual restored Panel HTTP.", flush=True)


if __name__ == "__main__":
    main()
